INSERT INTO `posts` VALUES (2,2,'du-hoc-uc','Du học Úc','<p>Du học úc .................................................</p>',3,'/assets/uploads/post_cover_1767958912_012d5dc4.jpg','<h1 align=\"center\" style=\"margin:0in;margin-bottom:.0001pt;text-align:center\"><a name=\"_Toc192576138\"><span style=\"font-size:15.0pt;line-height:150%\">CHƯƠNG 1:\r\nTỔNG QUAN VỀ CƠ SỞ THỰC TẬP</span></a><span style=\"font-size:15.0pt;line-height:\r\n150%\"><o:p></o:p></span></h1><h2 style=\"margin:0in\"><a name=\"_Toc192576139\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">1.1. Giới thiệu chung</span></a><span style=\"font-size:14.0pt;\r\nline-height:150%\"><o:p></o:p></span></h2><h3 style=\"margin:0in\"><a name=\"_Toc192576140\">1.1.1. Quá trình hình thành và\r\nphát triển</a><o:p></o:p></h3><p class=\"MsoNormal\" align=\"center\" style=\"text-align:center;page-break-after:avoid\"><v:shapetype id=\"_x0000_t75\" coordsize=\"21600,21600\" o:spt=\"75\" o:preferrelative=\"t\" path=\"m@4@5l@4@11@9@11@9@5xe\" filled=\"f\" stroked=\"f\">\r\n <v:stroke joinstyle=\"miter\">\r\n <v:formulas>\r\n  <v:f eqn=\"if lineDrawn pixelLineWidth 0\">\r\n  <v:f eqn=\"sum @0 1 0\">\r\n  <v:f eqn=\"sum 0 0 @1\">\r\n  <v:f eqn=\"prod @2 1 2\">\r\n  <v:f eqn=\"prod @3 21600 pixelWidth\">\r\n  <v:f eqn=\"prod @3 21600 pixelHeight\">\r\n  <v:f eqn=\"sum @0 0 1\">\r\n  <v:f eqn=\"prod @6 1 2\">\r\n  <v:f eqn=\"prod @7 21600 pixelWidth\">\r\n  <v:f eqn=\"sum @8 21600 0\">\r\n  <v:f eqn=\"prod @7 21600 pixelHeight\">\r\n  <v:f eqn=\"sum @10 21600 0\">\r\n </v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:f></v:formulas>\r\n <v:path o:extrusionok=\"f\" gradientshapeok=\"t\" o:connecttype=\"rect\">\r\n <o:lock v:ext=\"edit\" aspectratio=\"t\">\r\n</o:lock></v:path></v:stroke></v:shapetype><v:shape id=\"Picture_x0020_1\" o:spid=\"_x0000_i1028\" type=\"#_x0000_t75\" alt=\"Logo\" style=\"width:170.25pt;height:87.75pt;visibility:visible;\r\n mso-wrap-style:square\">\r\n <v:imagedata src=\"file:///C:/Users/MANH/AppData/Local/Temp/msohtmlclip1/01/clip_image001.png\" o:title=\"Logo\">\r\n</v:imagedata></v:shape><o:p></o:p></p><p class=\"MsoCaption\" align=\"center\" style=\"text-align:center\"><a name=\"_Toc192535490\"><b><span style=\"font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\">Hình 1.</span></b></a><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535490\'></span><span style=\'mso-element:field-begin\'></span><span\r\nstyle=\'mso-bookmark:_Toc192535490\'><b style=\'mso-bidi-font-weight:normal\'><span\r\nstyle=\'font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\'> SEQ\r\nHình_1. \\* ARABIC <span style=\'mso-element:field-separator\'></span></span></b></span><![endif]--><b><span style=\"font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\">1</span></b><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535490\'></span><span style=\'mso-element:field-end\'></span><![endif]--><b><span style=\"font-size:14.0pt;mso-bidi-font-size:12.0pt;color:windowtext\">: Logo Công\r\nty</span></b><b><span style=\"font-size: 14pt; color: windowtext; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p></o:p></span></b></p><p class=\"MsoNormal\" style=\"text-indent:.5in\"><a name=\"_heading=h.w16bjt4h5x9h\"></a>Công\r\nty cổ phần giải pháp phần mềm tài chính (FSS) được thành lập ngày 18/03/2008\r\nbởi các chuyên gia đã có nhiều năm kinh nghiệm trong việc phát triển và triển\r\nkhai giải pháp công nghệ thông tin cho các đơn vị hoạt động trong lĩnh vực tài\r\nchính, ngân hàng, chứng khoán tại Việt Nam và khu vực.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:.5in\">Sau 16 năm hoạt động, với một đội\r\nngũ hơn 400 chuyên gia làm việc trong lĩnh vực phần mềm, FSS đã trở thành một\r\ntrong những công ty phần mềm tài chính – ngân hàng hàng đầu tại Việt Nam và\r\nđược nhiều khách hàng tin tưởng, lựa chọn. Khách hàng của FSS bao gồm các ngân\r\nhàng và các công ty chứng khoán lớn như BIDV, TechcomBank, VPBank, MBBank,\r\nVNDirect, VCBS, BSC, BVSC,…<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:.5in\">Với phương châm hoạt động dựa trên\r\nsự cam kết lâu dài, tính chuyên nghiệp cao và hiểu biết sâu sắc nhu cầu khách\r\nhàng, FSS luôn nỗ lực hết mình để mang lại sự thành công và lợi ích lâu dài cho\r\nkhách hàng.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.4pt\">Công ty cổ phần giải pháp phần\r\nmềm tài chính FSS mong muốn và không ngừng nỗ lực để trở thành công ty hàng đầu\r\nở Việt Nam và có tên tuổi trong khu vực trong lĩnh vực cung cấp sản phẩm và\r\ndịch vụ phần mềm tài chính – ngân hàng; thông qua các sản phẩm, dịch vụ của\r\nmình mang lại sự thành công cho khách hàng, cổ đông, nhân viên công ty và đóng\r\ngóp cho cộng đồng<span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">.<o:p></o:p></span></p><h3 style=\"margin:0in\"><a name=\"_Toc192576141\">1.1.2. Chức năng và nhiệm vụ</a><o:p></o:p></h3><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l13 level1 lfo1\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>Kinh nghiệm và đội ngũ<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Đội ngũ nhân sự của FSS bao gồm\r\ncác chuyên gia hàng đầu trong lĩnh vực phần mềm tài chính – ngân hàng tại Việt\r\nnam. Với việc liên tục làm việc và tích lũy kinh nghiệm trong lĩnh vực này 15 -\r\n20 năm, FSS có khả năng thấu hiểu được các yêu cầu nghiệp vụ của khách hàng,\r\nqua đó đưa ra những giải pháp công nghệ phù hợp nhất, đảm bảo quá trình triển\r\nkhai dự án thành công.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l13 level1 lfo1\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>Sản phẩm<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Các sản phẩm của FSS được nghiên\r\ncứu, đầu tư xây dựng dựa trên các chuẩn mực quốc tế về sản phẩm phần mềm, đồng\r\nthời kết hợp giữa các kiến thức nghiệp vụ chuẩn quốc tế với các thực tiễn\r\nnghiệp vụ tại Việt Nam. Các sản phẩm phần mềm sàn giao dịch vàng, sàn giao dịch\r\nhàng hóa, core giao dịch chứng khoán của FSS đều được đánh giá thuộc loại sản\r\nphẩm tốt nhất trên thị trường Việt Nam.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l14 level1 lfo2\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>Cam kết lâu dài<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">FSS luôn cam kết cao và lâu dài\r\nvới khách hàng và thị trường. Các dự án do FSS triển khai có tỷ lệ thành công\r\n100%. Ngoài ra, FSS liên tục đầu tư vào phát triển sản phẩm và đội ngũ nhằm mục\r\nđích cung cấp được các sản phẩm và dịch vụ tốt nhất không những hiện tại mà cả\r\ntương lai. Một trong những mục tiêu chiến lược của FSS là đồng hành cùng khách\r\nhàng trong suốt quá trình phát triển của khách hàng.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l14 level1 lfo2\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>Quy trình phù hợp<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">FSS không áp dụng một quy trình\r\nxây dựng và triển khai phần mềm chung cho tất cả các dự án. Ở FSS, mỗi loại\r\nhình dự án được nghiên cứu, xây dựng và áp dụng một quy trình phù hợp, bao gồm\r\ntừ tổ chức dự án, các bước tiến hành dự án đến các mẫu biểu chi tiết cho loại\r\nhình dự án đó.<o:p></o:p></p><h3 style=\"margin:0in\"><a name=\"_Toc192576142\">1.1.3. Lĩnh vực hoạt động</a><o:p></o:p></h3><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l2 level1 lfo3\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->FSS hoạt động trong lĩnh vực cung cấp và triển khai các\r\nsản phẩm dịch vụ phần mềm cho các ngân hàng, công ty chứng khoán và các tổ chức\r\ntài chính. Hiện tại, FSS cung cấp và triển khai các sản phẩm dịch vụ phần mềm\r\ncho 3 lĩnh vực chính:<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l2 level1 lfo3\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Cung cấp và triển khai hệ thống core giao dịch chứng\r\nkhoán.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l2 level1 lfo3\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Triển khai hệ thống Data warehouse &amp; Business\r\nIntelligence cho các ngân hàng.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l2 level1 lfo3\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Cung cấp các dịch vụ tư vấn, phát triển và triển khai\r\nphần mềm theo yêu cầu cho các khách hàng lớn như Tổng cục thuế, Trung tâm Lưu\r\nký Chứng khoán Việt Nam....<o:p></o:p></p><h3 style=\"margin:0in\"><a name=\"_Toc192576143\">1.1.4. Cơ cấu, tổ chức quản lý</a><o:p></o:p></h3><p class=\"MsoNormal\" style=\"text-indent:.5in\">Cơ cấu tổ chức Công ty FSS được minh\r\nhọa dưới sơ đồ sau đây:<o:p></o:p></p><p class=\"MsoNormal\" align=\"center\" style=\"text-align:center;page-break-after:avoid\"><v:shape id=\"Picture_x0020_8\" o:spid=\"_x0000_i1027\" type=\"#_x0000_t75\" style=\"width:439.5pt;height:246.75pt;\r\n visibility:visible;mso-wrap-style:square\">\r\n <v:imagedata src=\"file:///C:/Users/MANH/AppData/Local/Temp/msohtmlclip1/01/clip_image002.png\" o:title=\"\">\r\n</v:imagedata></v:shape><o:p></o:p></p><p class=\"MsoCaption\" align=\"center\" style=\"text-align:center\"><a name=\"_Toc192535491\"><b><span style=\"font-size:14.0pt;mso-bidi-font-size:9.0pt;color:windowtext\">Hình 1.</span></b></a><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535491\'></span><span style=\'mso-element:field-begin\'></span><span\r\nstyle=\'mso-bookmark:_Toc192535491\'><b style=\'mso-bidi-font-weight:normal\'><span\r\nstyle=\'font-size:14.0pt;mso-bidi-font-size:9.0pt;color:windowtext\'> SEQ Hình_1.\r\n\\* ARABIC <span style=\'mso-element:field-separator\'></span></span></b></span><![endif]--><b><span style=\"font-size:14.0pt;mso-bidi-font-size:9.0pt;color:windowtext\">2</span></b><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535491\'></span><span style=\'mso-element:field-end\'></span><![endif]--><b><span style=\"font-size:14.0pt;mso-bidi-font-size:9.0pt;color:windowtext\">: Cơ cấu tổ\r\nchức của Công ty FSS</span></b><b><span style=\"font-size:14.0pt;mso-bidi-font-size:9.0pt;color:windowtext\"><o:p></o:p></span></b></p><h2 style=\"margin:0in\"><a name=\"_Toc192576144\"></a><a name=\"_heading=h.f1gskv5nih7j\"></a><span style=\"font-size:14.0pt;line-height:150%\">1.2. Sản phẩm và dịch vụ</span><span style=\"font-size:14.0pt;line-height:150%\"><o:p></o:p></span></h2><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l20 level1 lfo4\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>CBOND - Hệ thống giao dịch trái phiếu doanh\r\nnghiệp<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.4pt\">Hệ thống giao dịch trái phiếu\r\ndoanh nghiệp được thiết kế xây dựng với mục tiêu cung cấp một nền tảng thỏa\r\nthuận điện tử ngang hàng cho tất cả các thành phần tham gia quá trình đầu tư\r\nvào trái phiếu doanh nghiệp.<o:p></o:p></p><p class=\"MsoNormal\" align=\"center\" style=\"text-align:center;text-indent:35.4pt;\r\npage-break-after:avoid\"><v:shape id=\"Picture_x0020_9\" o:spid=\"_x0000_i1026\" type=\"#_x0000_t75\" alt=\"https://fss.com.vn/uploaded/San%20pham%20va%20dich%20vu/CBOND%20(2).png\" style=\"width:315pt;height:179.25pt;visibility:visible;mso-wrap-style:square\">\r\n <v:imagedata src=\"file:///C:/Users/MANH/AppData/Local/Temp/msohtmlclip1/01/clip_image003.png\" o:title=\"CBOND%20(2)\">\r\n</v:imagedata></v:shape><o:p></o:p></p><p class=\"MsoCaption\" align=\"center\" style=\"text-align:center\"><a name=\"_Toc192535492\"><b><span style=\"font-size:14.0pt;color:windowtext\">Hình 1.</span></b></a><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535492\'></span><span style=\'mso-element:field-begin\'></span><span\r\nstyle=\'mso-bookmark:_Toc192535492\'><b style=\'mso-bidi-font-weight:normal\'><span\r\nstyle=\'font-size:14.0pt;color:windowtext\'> SEQ Hình_1. \\* ARABIC <span\r\nstyle=\'mso-element:field-separator\'></span></span></b></span><![endif]--><b><span style=\"font-size:14.0pt;color:windowtext\">3</span></b><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535492\'></span><span style=\'mso-element:field-end\'></span><![endif]--><b><span style=\"font-size:14.0pt;color:windowtext\">: Lưu đồ hệ thống CBOND</span></b><b><span style=\"font-size:14.0pt;color:windowtext\"><o:p></o:p></span></b></p><p class=\"MsoNormal\">Trong đó:<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l18 level1 lfo5\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Issuer: Là đối tượng phát hành ra trái phiếu doanh\r\nnghiệp. <o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l18 level1 lfo5\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Remiser/Agent: Là mạng lưới môi giới phát triển khách\r\nhàng (nhà đầu tư).<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l18 level1 lfo5\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Broker/Dealer: Là đại lý phát hành, nhà tạo lập thị\r\ntrường để bán tài sản đầu tư cho khách hàng, tạo thanh khoản thông qua việc\r\nliên tục chào MUA/BÁN.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l18 level1 lfo5\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Investor: Là nhà đầu tư (khách hàng).<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l18 level1 lfo5\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Commercial Bank: Là ngân hàng cung cấp dịch vụ thanh\r\ntoán tiền.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l18 level1 lfo5\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Broker House Securites: Là công ty chứng khoán cung cấp\r\ncổng giao dịch cho trái phiếu doanh nghiệp niêm yết tại SGDCK.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l11 level1 lfo6\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>iFTP - Hệ thống giá vốn nội bộ và phân bổ\r\nchi phí iFTP<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Sản phẩm iFTP được FSS xây dựng\r\ndựa trên nền tảng cơ sở dữ liệu Data warehouse của Ngân hàng. Sản phẩm iFTP\r\ncung cấp bộ tham số linh hoạt, cho phép Ngân hàng tự khai báo các công thức\r\ntính toán giá vốn và phân bổ chi phí, đồng thời hỗ trợ tốt các ngoại lệ đặc thù\r\ntại thị trường ngân hàng Việt Nam.<o:p></o:p></p><p class=\"MsoNormal\">iFTP hỗ trợ các bộ phận nghiệp vụ:<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Khai báo giá mua/bán vốn nội bộ trong ngân hàng.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Khai báo công thức và các bước phân bổ chi phí cho các\r\nkhối/phòng ban.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Bộ báo cáo về giá mua bán vốn, NIM, PnL của từng tài\r\nkhoản/khách hàng.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Bộ báo cáo phân bổ chi phí: Báo cáo PnL trước và sau\r\nphân bổ chi phí theo từng khối, phòng ban, bộ phận.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Hiện tại sản phẩm FTP&amp;Cost\r\nAllocation đã được triển khai thành công tại Ngân hàng TMCP&nbsp; Hàng Hải&nbsp;\r\nViệt Nam (Maritime Bank) và Ngân hàng TMCP Đại chúng Việt Nam\r\n(PVcomBank), Ngân hàng TMCP Tiên Phong (TPBank), Ngân hàng TMCP Quốc Dân (NCB)\r\nvà Ngân hàng Bưu Điện Liên việt (LienVietPostBank).<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l10 level1 lfo8\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>FLEX - Hệ thống giao dịch chứng khoán FLEX<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">FLEX là hệ thống phần mềm quản\r\nlý và giao dịch chứng khoán được thiết kế dựa trên kiến trúc nền tảng tài chính\r\n(financial framework), với các tham số linh hoạt, cho phép các công ty chứng\r\nkhoán vừa đẩy mạnh kinh doanh bằng cách đa dạng hóa sản phẩm, vừa kiểm soát\r\nđược các rủi ro gắn liền với các sản phẩm đó. FLEX cũng hỗ trợ tự động hóa hoàn\r\ntoàn quy trình giao dịch của công ty chứng khoán, tối ưu hóa hiệu quả hoạt động\r\ncủa công ty chứng khoán.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Những đặc điểm nổi bật của Hệ\r\nthống quản lý và giao dịch chứng khoán FLEX bao gồm:<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Giao dịch trực tuyến: Các giao dịch được hiện từ xa,\r\nmọi lúc, mọi nơi và an toàn qua tất cả các kênh giao dịch web trading, home\r\ntrading, mobile trading.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tham số linh hoạt cho phép các công ty chứng khoán\r\nthiết kế các sản phẩm nghiệp vụ và chính sách cho nhà đầu tư đa dạng, linh\r\nhoạt; đặc biệt là các sản phẩm và dịch vụ tài chính: Margin, ứng trước, cầm cố,\r\nbảo lãnh...<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Kiểm soát rủi ro chặt chẽ: Rủi ro quy trình, rủi ro sản\r\nphẩm, rủi ro từ phía nhà đầu tư, rủi ro chính sách…<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tự động xử lý nhiều loại nghiệp vụ.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tích hợp dễ dàng với các hệ thống khác như: Hệ thống\r\ngiao dịch của Sở giao dịch chứng khoán, hệ thống core banking của Ngân hàng,\r\nphần mềm kế toán nội bộ, hệ thống đặt lệnh Bloomberg, Reuters…<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Resfull Open API: Cho phép các hệ thống, các công cụ\r\ngiao dịch, các robot trading có thể dễ dàng tích hợp giao dịch qua hệ thống\r\nFLEX. <o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tăng khả năng cạnh tranh, giảm chi phí hoạt động và hỗ\r\ntrợ ra quyết định.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">FLEX&nbsp; hiện đã được triển khai thành công ở hơn 20\r\ncông ty chứng khoán và được đánh giá là một trong những sản phẩm core chứng\r\nkhoán tốt nhất trên thị trường Việt Nam hiện nay. Danh sách các công ty chứng\r\nkhoán sử dụng sản phẩm Flex bao gồm: Công ty chứng khoán VNDirect, công ty\r\nchứng khoán Vietcombank, công ty chứng khoán Bảo Việt, công ty chứng khoán\r\nBIDV, công ty chứng khoán KBSV, công ty chứng khoán Phú Hưng, công ty chứng\r\nkhoán Techcombank….<o:p></o:p></p><h2 style=\"margin:0in\"><a name=\"_Toc192576145\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">1.3. Môi trường làm việc</span></a><span style=\"font-size:\r\n14.0pt;line-height:150%\"><o:p></o:p></span></h2><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l15 level1 lfo9\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>Chủ động tạo ra thử thách để phát triển bản\r\nthân<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">FSS là một môi trường luôn\r\nkhuyến khích tinh thần đổi mới và sáng tạo. Với mô hình lãnh đạo lấy con người\r\nlàm trung tâm, đội ngũ quản lý tại FSS luôn đồng hành và thúc đẩy mỗi cá nhân\r\nphát huy tối đa tiềm năng của mình.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Tại đây, mỗi FSSer không chỉ làm\r\nviệc mà còn tự tạo ra những thử thách ý nghĩa, giúp bản thân không ngừng phát\r\ntriển. Thay vì chờ đợi hướng dẫn, họ chủ động tìm kiếm cơ hội, nỗ lực hết mình\r\nvà đóng góp giá trị cho tổ chức.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l15 level1 lfo9\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>Văn hóa học tập liên tục để bứt phá<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">FSS xây dựng một tổ chức học tập\r\ntoàn diện, nơi mỗi cá nhân có thể phát triển bản thân thông qua môi trường hỗ\r\ntrợ, cơ hội học hỏi đa dạng và năng lực học tập chủ động:<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Môi trường học tập: FSSer được\r\ntiếp cận kho tài liệu phong phú, hệ thống đào tạo bài bản và văn hóa chia sẻ\r\nkiến thức liên tục, giúp việc học trở nên dễ dàng và hiệu quả.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Cơ hội học tập: Với các chương\r\ntrình đào tạo chuyên sâu, khóa học trực tuyến, hỗ trợ học phí và cơ hội thử\r\nthách bản thân trong công việc thực tế, FSS mang đến lộ trình phát triển phù\r\nhợp cho từng cá nhân.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Năng lực học tập: Mỗi FSSer được\r\ntrang bị phương pháp học tập cá nhân hóa, kết hợp giữa kinh nghiệm thực tiễn,\r\nhọc hỏi từ đồng nghiệp và kiến thức nền tảng, đảm bảo sự phát triển bền vững.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:35.45pt;mso-list:l15 level1 lfo9\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><b><i>Văn hóa gắn kết và đề cao giá trị con người<o:p></o:p></i></b></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">FSS tin rằng sự thành công không\r\nchỉ đến từ kết quả công việc mà còn từ niềm vui và sự gắn kết của mỗi thành\r\nviên. Mọi chính sách và hoạt động tại FSS đều hướng đến việc tạo ra một môi\r\ntrường làm việc nhân văn, nơi mỗi cá nhân được tôn trọng, phát triển thế mạnh\r\nvà tìm thấy niềm hạnh phúc trong công việc.<o:p></o:p></p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Từ các hoạt động nội bộ gắn kết\r\nđến sự quan tâm chân thành giữa đồng nghiệp, FSS không chỉ là nơi làm việc mà\r\ncòn là một gia đình, nơi mỗi thành viên luôn tự hào khi đồng hành cùng nhau.<br clear=\"all\" style=\"mso-special-character:line-break;page-break-before:always\">\r\n<o:p></o:p></p><h1 align=\"center\" style=\"margin:0in;margin-bottom:.0001pt;text-align:center\"><a name=\"_Toc192576146\"><span style=\"font-size:15.0pt;line-height:150%\">CHƯƠNG 2:\r\nQUÁ TRÌNH THỰC TẬP TẠI ĐƠN VỊ</span></a><span style=\"font-size:15.0pt;\r\nline-height:150%\"><o:p></o:p></span></h1><h2 style=\"margin:0in\"><a name=\"_Toc192576147\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">2.1. Quy định chung</span></a><span style=\"font-size:14.0pt;\r\nline-height:150%\"><o:p></o:p></span></h2><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Trong quá trình thực tập mỗi ngày, sinh viên thực tập\r\ntại công ty từ 8h30’ đến 17h30 nghỉ trưa từ 12h00 đến 13h00.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tìm hiểu và sử dụng Zimbra làm kênh trao đổi, báo cáo,\r\nthảo luận chung trong dự án.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Sử dụng Jira để quản lý và theo dõi công việc, bao gồm\r\ntạo và phân công nhiệm vụ, cập nhật tiến độ, cũng như ghi nhận các vấn đề phát\r\nsinh trong quá trình thực hiện.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Làm quen với quy trình làm việc của nhóm, nắm bắt cách\r\nphối hợp giữa các thành viên để đảm bảo tiến độ dự án.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tham gia các buổi họp nhóm, cập nhật tiến độ công việc\r\ncá nhân, trao đổi ý kiến và đề xuất giải pháp khi gặp khó khăn.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Thực hiện các nhiệm vụ được giao theo kế hoạch, đảm bảo\r\nđúng tiến độ và chất lượng yêu cầu.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Hỗ trợ kiểm thử và đánh giá kết quả, ghi nhận lỗi và đề\r\nxuất cải tiến nếu cần thiết.<o:p></o:p></p><h2 style=\"margin:0in\"><a name=\"_Toc192576148\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">2.2. Nhiệm vụ được giao</span></a><span style=\"font-size:\r\n14.0pt;line-height:150%\"><o:p></o:p></span></h2><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tìm hiểu lý thuyết cơ bản về kiểm thử.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tìm hiểu về kiến thức tài chính, ngân hàng.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tham gia quy trình kiểm thử phần mềm theo mô hình\r\nAgile/Scrum.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Phân tích, nghiên cứu luồng nghiệp vụ.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Viết kịch bản kiểm thử (Test case/Checklist).<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Kiểm thử giao diện Website/App.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Thực thi kiểm thử API.<o:p></o:p></p><h2 style=\"margin:0in\"><a name=\"_Toc192576149\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">2.3. Giải pháp thực hiện</span></a><span style=\"font-size:\r\n14.0pt;line-height:150%\"><o:p></o:p></span></h2><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tìm hiểu lý thuyết cơ bản về kiểm thử: Nắm vững 7\r\nnguyên tắc kiểm thử, quá trình kiểm thử phần mềm và các loại kiểm thử hộp đen\r\n(Black-box testing).<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tìm hiểu về kiến thức tài chính, ngân hàng: Nghiên cứu\r\ncác khái niệm về giao dịch chứng khoán, cổ phiếu, trái phiếu, và các nghiệp vụ\r\ntài chính liên quan.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Nghiên cứu mô hình Agile và Scrum: Hiểu về quy trình\r\nphát triển phần mềm linh hoạt, vai trò của các thành viên trong nhóm Scrum và\r\ncách thức thực hiện kiểm thử trong mô hình này.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Phân tích tài liệu dự án: Đọc hiểu tài liệu yêu cầu và\r\ntài liệu đặc tả, từ đó xác định luồng nghiệp vụ cần kiểm thử trên hệ thống.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Tìm hiểu các kỹ thuật kiểm thử: Áp dụng các phương pháp\r\nkiểm thử như kiểm thử phân vùng tương đương, phân tích giá trị biên, kiểm thử\r\ndựa trên bảng quyết định,...<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Kiểm thử giao diện Website/App: Kiểm tra tính nhất quán\r\ncủa giao diện theo thiết kế (UI/UX), đảm bảo bố cục, màu sắc, font chữ và\r\nkhoảng cách hiển thị đúng chuẩn. Thực hiện kiểm thử trên nhiều trình duyệt\r\n(cross-browser testing) và nhiều thiết bị khác nhau để đảm bảo trải nghiệm\r\nngười dùng tốt nhất. Kiểm tra khả năng phản hồi (responsive) và tính tương tác\r\ncủa các thành phần giao diện.<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left:.5in;mso-list:l0 level1 lfo7\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Kiểm thử API với Postman: Tìm hiểu cách gửi request,\r\nkiểm tra response, thực hiện kiểm thử chức năng và kiểm thử hiệu năng API bằng\r\nPostman.<o:p></o:p></p><h2 style=\"margin:0in\"><a name=\"_Toc192576150\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">2.4. Kế hoạch thực hiện</span></a><span style=\"font-size:\r\n14.0pt;line-height:150%\"><o:p></o:p></span></h2><h3 style=\"margin:0in\"><a name=\"_Toc192576151\">2.4.1. Tìm hiểu lý thuyết cơ bản\r\nvề kiểm thử</a><o:p></o:p></h3><h4 style=\"margin:0in\"><a name=\"_Toc192576152\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">2.4.1.1. 7 nguyên tắc kiểm thử phần mềm</span></a><span style=\"font-size:14.0pt;line-height:150%\"><o:p></o:p></span></h4><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Kiểm\r\nthử chứng minh sự hiện diện của lỗi, không phải sự vắng mặt của lỗi:</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Mục\r\ntiêu của kiểm thử không phải để chứng minh phần mềm không có lỗi mà là để phát\r\nhiện lỗi.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Việc\r\nkiểm thử càng kỹ lưỡng, càng có nhiều lỗi được tìm ra, nhưng không thể đảm bảo\r\nhệ thống hoàn toàn không có lỗi.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Kiểm\r\nthử toàn bộ là không khả thi</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Không\r\nthể kiểm thử tất cả các trường hợp đầu vào, tình huống và kịch bản có thể xảy\r\nra do sự phức tạp của phần mềm. </span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Thay\r\nvào đó, kiểm thử tập trung vào các trường hợp quan trọng và có rủi ro cao để\r\ntối ưu thời gian và nguồn lực.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Kiểm\r\nthử càng sớm càng tốt</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Phát\r\nhiện lỗi ở giai đoạn đầu của vòng đời phát triển phần mềm giúp giảm chi phí và\r\ncông sức sửa lỗi.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Các\r\nhoạt động kiểm thử như Unit Test, Integration Test nên được thực hiện sớm để\r\ngiảm nguy cơ lỗi lan rộng.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Lỗi\r\nthường được phân bố tập trung</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Lỗi\r\nkhông xuất hiện đều trong phần mềm mà thường tập trung vào một số module hoặc\r\ntính năng nhất định.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Nguyên\r\ntắc này giúp tester ưu tiên kiểm thử các khu vực có nguy cơ cao, chẳng hạn như\r\nnhững phần thay đổi thường xuyên hoặc có lịch sử lỗi nhiều.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Nghịch\r\nlý thuốc trừ sâu</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Nếu\r\ncùng một bộ kiểm thử được sử dụng lặp đi lặp lại, hiệu quả phát hiện lỗi sẽ\r\ngiảm dần.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Để\r\nkhắc phục, cần cập nhật và cải tiến các test case thường xuyên để phát hiện lỗi\r\nmới.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Kiểm\r\nthử phụ thuộc vào ngữ cảnh</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"color:black;mso-color-alt:windowtext\">Mỗi loại phần mềm có yêu cầu kiểm\r\nthử khác nhau. Ví dụ:</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 63.8pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Phần\r\nmềm tài chính yêu cầu kiểm thử bảo mật nghiêm ngặt để đảm bảo an toàn dữ liệu\r\nvà giao dịch.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 63.8pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Ứng\r\ndụng giải trí cần tập trung vào kiểm thử hiệu suất và trải nghiệm người dùng để\r\nđảm bảo sự mượt mà, ổn định.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 63.8pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Hệ\r\nthống thương mại điện tử đòi hỏi kiểm thử tính năng giỏ hàng, thanh toán và\r\nhiệu suất khi có lượng truy cập lớn.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 0.5in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">ð<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Việc\r\nlựa chọn phương pháp kiểm thử phải phù hợp với đặc điểm và yêu cầu cụ thể của\r\ntừng loại phần mềm.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]--><span style=\"font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\">v<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">\r\n</span></span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Quan\r\nniệm sai lầm về việc “hết lỗi”</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Ngay\r\ncả khi phần mềm đã trải qua nhiều giai đoạn kiểm thử mà không phát hiện lỗi,\r\nđiều đó không đồng nghĩa với việc hệ thống hoàn toàn không có lỗi.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Phần\r\nmềm có thể hoạt động ổn định trong môi trường kiểm thử nhưng vẫn có nguy cơ gặp\r\nsự cố khi triển khai thực tế, do khác biệt về dữ liệu, cấu hình hệ thống hoặc\r\ncác tình huống không lường trước.</span><o:p></o:p></p><p class=\"MsoListParagraph\" style=\"margin-left: 35.45pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Ngoài\r\nra, khi có yêu cầu mới hoặc nâng cấp tính năng, các lỗi tiềm ẩn có thể xuất\r\nhiện, đòi hỏi quá trình kiểm thử liên tục và thích ứng.</span><o:p></o:p></p><h4 style=\"margin:0in\"><a name=\"_Toc192576153\"><span style=\"font-size:14.0pt;\r\nline-height:150%\">2.4.1.2. Quá trình kiểm thử phần mềm</span></a><span style=\"font-size:14.0pt;line-height:150%\"><o:p></o:p></span></h4><div style=\"border: 1pt none rgb(217, 217, 227); padding: 0in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; margin-left: 0.25in; margin-right: 0in;\">\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left: 0.25in; text-indent: -0.25in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-top: none; border-right: none; border-left: none; border-image: initial; padding: 0in; border-bottom: 0in none rgb(217, 217, 227);\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Xác\r\nđịnh mục tiêu kiểm thử: Đặt ra các mục tiêu cụ thể cho quá trình kiểm thử, xác\r\nđịnh rõ yêu cầu chức năng và phi chức năng của phần mềm.</span><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left: 0.25in; text-indent: -0.25in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-top: none; border-right: none; border-left: none; border-image: initial; padding: 0in; border-bottom: 0in none rgb(217, 217, 227);\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Lập\r\nkế hoạch kiểm thử: Xây dựng kế hoạch kiểm thử chi tiết, bao gồm lịch trình, tài\r\nnguyên, và các chiến lược kiểm thử như kiểm thử đơn vị, hệ thống, tích hợp, và\r\nchấp nhận.</span><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left: 0.25in; text-indent: -0.25in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-top: none; border-right: none; border-left: none; border-image: initial; padding: 0in; border-bottom: 0in none rgb(217, 217, 227);\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Phân\r\ntích yêu cầu: Kiểm tra và hiểu rõ yêu cầu của khách hàng để xác định các trường\r\nhợp kiểm thử và các kịch bản kiểm thử phù hợp.</span><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left: 0.25in; text-indent: -0.25in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-top: none; border-right: none; border-left: none; border-image: initial; padding: 0in; border-bottom: 0in none rgb(217, 217, 227);\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Thiết\r\nkế kiểm thử: Tạo các kịch bản kiểm thử và các bộ dữ liệu kiểm thử dựa trên các\r\nyêu cầu và thiết kế hệ thống.</span><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left: 0.25in; text-indent: -0.25in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-top: none; border-right: none; border-left: none; border-image: initial; padding: 0in; border-bottom: 0in none rgb(217, 217, 227);\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Thực\r\nhiện kiểm thử: Thực hiện các bước kiểm thử, chạy các kịch bản kiểm thử, và ghi\r\nlại kết quả để xác định xem phần mềm có đáp ứng đúng yêu cầu hay không.</span><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left: 0.25in; text-indent: -0.25in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-top: none; border-right: none; border-left: none; border-image: initial; padding: 0in; border-bottom: 0in none rgb(217, 217, 227);\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Bảo\r\ntrì và cập nhật: Hiệu chỉnh các kịch bản kiểm thử và cập nhật chiến lược kiểm\r\nthử dựa trên kết quả kiểm thử và sự thay đổi trong yêu cầu.</span><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left: 0.25in; text-indent: -0.25in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border: none; padding: 0in;\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]--><span style=\"color:black;mso-color-alt:windowtext\">Báo\r\ncáo và Đánh giá: Tạo báo cáo về các kết quả kiểm thử, bao gồm các lỗi phát hiện\r\nvà mức độ đáp ứng của phần mềm đối với yêu cầu.</span><o:p></o:p></p>\r\n\r\n</div><p class=\"MsoNormal\" align=\"center\" style=\"text-align:center;line-height:200%;\r\npage-break-after:avoid\"><v:shape id=\"Picture_x0020_28\" o:spid=\"_x0000_i1025\" type=\"#_x0000_t75\" alt=\"Quy trình kiểm thử phần mềm - Software testing life cycle( STLC)\" style=\"width:439.5pt;height:151.5pt;visibility:visible;mso-wrap-style:square\">\r\n <v:imagedata src=\"file:///C:/Users/MANH/AppData/Local/Temp/msohtmlclip1/01/clip_image004.png\" o:title=\"Quy trình kiểm thử phần mềm - Software testing life cycle( STLC)\">\r\n</v:imagedata></v:shape><o:p></o:p></p><p class=\"MsoCaption\" align=\"center\" style=\"text-align:center\"><a name=\"_Toc192535505\"><b><span style=\"font-size:14.0pt;color:windowtext\">Hình 2.</span></b></a><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535505\'></span><span style=\'mso-element:field-begin\'></span><span\r\nstyle=\'mso-bookmark:_Toc192535505\'><b style=\'mso-bidi-font-weight:normal\'><span\r\nstyle=\'font-size:14.0pt;color:windowtext\'> SEQ Hình_2. \\* ARABIC <span\r\nstyle=\'mso-element:field-separator\'></span></span></b></span><![endif]--><b><span style=\"font-size:14.0pt;color:windowtext\">1</span></b><!--[if supportFields]><span\r\nstyle=\'mso-bookmark:_Toc192535505\'></span><span style=\'mso-element:field-end\'></span><![endif]--><b><span style=\"font-size:14.0pt;color:windowtext\">: Quá trình kiểm thử phần mềm</span></b><a name=\"_heading=h.42aabrbtss7w\"></a><b><span style=\"font-size:14.0pt;color:windowtext\"><o:p></o:p></span></b></p><h4 style=\"margin:0in\"><a name=\"_Toc192576154\"></a><a name=\"_heading=h.fka2319jyjzl\"></a><span style=\"font-size:14.0pt;line-height:150%\">2.4.1.3. Các loại kiểm thử hộp đen</span><span style=\"font-size:14.0pt;line-height:150%\"><o:p></o:p></span></h4><div style=\"mso-element:para-border-div;border:none #D9D9E3 1.0pt;mso-border-alt:\r\nnone #D9D9E3 0in;padding:0in 0in 0in 0in\">\r\n\r\n<p class=\"MsoNormal\" style=\"text-indent:35.45pt;border:none;mso-border-alt:none #D9D9E3 0in;\r\npadding:0in;mso-padding-alt:0in 0in 0in 0in;mso-border-between:0in none #D9D9E3;\r\nmso-padding-between:0in\">Kiểm thử hộp đen (Black box Testing) là một phương\r\npháp kiểm thử tập trung vào kiểm tra các chức năng của phần mềm mà không yêu\r\ncầu kiến thức về cấu trúc bên trong của mã nguồn. Người kiểm thử xem xét và\r\nkiểm tra các đầu vào và đầu ra của phần mềm mà không biết cách nó được triển\r\nkhai. Dưới đây là một số loại kiểm thử hộp đen phổ biến:<o:p></o:p></p>\r\n\r\n</div><div style=\"mso-element:para-border-div;border:none #D9D9E3 1.0pt;mso-border-alt:\r\nnone #D9D9E3 0in;padding:0in 0in 0in 0in;margin-left:.25in;margin-right:0in\">\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left:.25in;text-indent:-.25in;mso-pagination:\r\nwidow-orphan;mso-list:l12 level1 lfo22;border:none;mso-border-alt:none #D9D9E3 0in;\r\npadding:0in;mso-padding-alt:0in 0in 0in 0in;mso-border-between:0in none #D9D9E3;\r\nmso-padding-between:0in;padding-bottom:0in;mso-padding-bottom-alt:0in;\r\nborder-bottom:0in none #D9D9E3;mso-border-bottom-alt:0in none #D9D9E3\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Kiểm thử chức năng (Functionality Testing): Đảm bảo\r\nrằng chức năng của phần mềm hoạt động đúng theo yêu cầu.<o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left:.25in;text-indent:-.25in;mso-pagination:\r\nwidow-orphan;mso-list:l12 level1 lfo22;border:none;mso-border-alt:none #D9D9E3 0in;\r\npadding:0in;mso-padding-alt:0in 0in 0in 0in;mso-border-between:0in none #D9D9E3;\r\nmso-padding-between:0in;padding-top:0in;mso-padding-top-alt:0in;padding-bottom:\r\n0in;mso-padding-bottom-alt:0in;border-bottom:0in none #D9D9E3;mso-border-bottom-alt:\r\n0in none #D9D9E3\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Kiểm thử giao diện Người dùng (User Interface Testing):\r\nKiểm thử tính thân thiện và dễ sử dụng của giao diện người dùng.<o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-left:.25in;text-indent:-.25in;mso-pagination:\r\nwidow-orphan;mso-list:l12 level1 lfo22;border:none;mso-border-alt:none #D9D9E3 0in;\r\npadding:0in;mso-padding-alt:0in 0in 0in 0in;mso-border-between:0in none #D9D9E3;\r\nmso-padding-between:0in;padding-top:0in;mso-padding-top-alt:0in\"><!--[if !supportLists]-->-<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span><!--[endif]-->Kiểm thử tương tác (Integration Testing): Đảm bảo tích\r\nhợp giữa các thành phần hoạt động đúng đắn.<o:p></o:p></p>\r\n\r\n</div><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"text-indent:35.45pt\">Kiểm thử hệ thống (System\r\nTesting): Kiểm thử toàn bộ hệ thống để đảm bảo rằng nó hoạt động đúng theo\r\nthiết kế.<o:p></o:p></p>',1,0,1,'2026-01-09 11:41:53','2026-01-09 11:46:10',13,NULL);
